<style>
.contact-page{background:#f7f8fb;min-height:70vh;padding:56px 5% 80px;font-family:Inter,system-ui,sans-serif}.contact-wrap{max-width:1180px;margin:auto}.contact-head{text-align:center;margin-bottom:30px}.contact-head h1{font-size:38px;margin:0;color:#172033}.contact-head p{color:#768092;font-size:13px}.contact-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:22px}.contact-card{background:#fff;border:1px solid #e8eaf0;border-radius:20px;padding:26px;box-shadow:0 10px 30px rgba(25,32,50,.04)}.contact-card h3{margin:0 0 18px;color:#172033}.contact-item{display:flex;gap:12px;margin:18px 0}.contact-item i{width:40px;height:40px;border-radius:12px;background:#f0efff;color:#5b54ea;display:grid;place-items:center}.contact-item strong{display:block;font-size:13px}.contact-item span{font-size:12px;color:#768092}.cf-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.cf-group{margin-bottom:15px}.cf-group label{display:block;font-size:12px;font-weight:700;color:#455066;margin-bottom:7px}.cf-group input,.cf-group textarea{width:100%;box-sizing:border-box;border:1px solid #dfe3ea;border-radius:11px;padding:12px 13px;font:inherit;font-size:13px;outline:none}.cf-group textarea{min-height:140px;resize:vertical}.cf-group input:focus,.cf-group textarea:focus{border-color:#8d82ff;box-shadow:0 0 0 3px rgba(91,84,234,.08)}.cf-btn{border:0;border-radius:11px;padding:12px 18px;background:#5b54ea;color:#fff;font-weight:800;cursor:pointer}.cf-msg{margin-top:12px;font-size:12px}@media(max-width:750px){.contact-grid{grid-template-columns:1fr}.cf-row{grid-template-columns:1fr}}
</style>
<div class="contact-page"><div class="contact-wrap"><div class="contact-head"><h1>We’re here to help</h1><p>Questions about a book, order, rental or account? Send us a message.</p></div><div class="contact-grid"><div class="contact-card"><h3>Contact BookSpot</h3><div class="contact-item"><i class="fa-regular fa-envelope"></i><div><strong>Email</strong><span>support@bookspot.local</span></div></div><div class="contact-item"><i class="fa-solid fa-phone"></i><div><strong>Phone</strong><span>Mon–Sat · 10:00 AM–7:00 PM</span></div></div><div class="contact-item"><i class="fa-solid fa-location-dot"></i><div><strong>Online support</strong><span>Reader support across India.</span></div></div></div><div class="contact-card"><h3>Send a message</h3><form id="contactForm"><div class="cf-row"><div class="cf-group"><label>Name</label><input name="name" required maxlength="150"></div><div class="cf-group"><label>Email</label><input type="email" name="email" required maxlength="150"></div></div><div class="cf-group"><label>Message</label><textarea name="message" required maxlength="3000"></textarea></div><button class="cf-btn" type="submit"><i class="fa-solid fa-paper-plane"></i> Send Message</button><div id="contactMsg" class="cf-msg"></div></form></div></div></div></div>
<script>
document.getElementById('contactForm')?.addEventListener('submit',function(e){e.preventDefault();const out=document.getElementById('contactMsg');out.textContent='Sending…';fetch('<?= site_url('contact/send'); ?>',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:new FormData(this)}).then(r=>r.json()).then(d=>{out.textContent=d.message;out.style.color=d.status==='success'?'#18875b':'#d84550';if(d.status==='success')this.reset();}).catch(()=>{out.textContent='Unable to send right now.';out.style.color='#d84550';});});
</script>